function school(){const rows=arr('okulBilgileri');return rows.find(x=>x.id==='ayarlar')||rows[0]||{}}
function teachers(){return arr('ogretmenler')}
function adminNames(){const o=school(),ts=teachers(),mudur=ts.find(t=>t.id===o.mudurId)||ts.find(t=>(t.unvan||'').trim()==='Müdür'),yrd=ts.find(t=>(t.unvan||'').trim()==='Müdür Yardımcısı'),name=t=>t?`${t.ad||''} ${t.soyad||''}`.trim():'';return{mudur:name(mudur),yardimci:name(yrd)}}
