function currentPlan(servisId){return arr('servisOturma').find(p=>p.servisId===servisId||p.id===servisId)||null}
function busSeats(){const editable=canEditBusSeats(),list=arr('servisler').filter(s=>match([s.servisAdi,s.guzergah,s.plaka,currentPlan(s.id)?.sablon])).sort((a,b)=>serviceName(a).localeCompare(serviceName(b),'tr'));return listResult(list,s=>{const p=currentPlan(s.id),els=window.soPlanElementleriGetir?.(p||{},p?.sablon||'ducato')||[],st=window.soElementIstatistik?.(els)||{toplam:0,dolu:0};return `<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><div class="ka-grow"><strong>${esc(serviceName(s))}</strong><div class="ka-muted">${esc(window.SO_SABLONLAR?.[p?.sablon]?.ad||p?.sablon||'Henüz plan yok')}</div></div><span class="ka-badge">${st.dolu}/${st.toplam||'—'}</span><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-bus-edit="${esc(s.id)}">${editable?'Düzenle':'Görüntüle'}</button></div></article>`},'Servis kaydı bulunamadı.')}
