  picker.innerHTML=`<section class="ka-modal ka-bus-seat-picker__modal"><div class="ka-modal__header"><div><h3>Koltuk ${esc(seat.seatNumber||index+1)}</h3><div class="ka-muted">${esc(seatStudentName(seat)||(seat.properties?.reserved?'Rezerve':'Öğrenci seçin'))}</div></div><button class="ka-icon-button" type="button" data-bus-picker-close>×</button></div><div class="ka-modal__body ka-stack"><label class="ka-field"><span class="ka-field__label">Öğrenci ara</span><input type="search" data-bus-student-search placeholder="Ad, numara veya sınıf…" autocomplete="off"></label><div class="ka-bus-student-list" data-bus-student-list>${renderOptions('')}</div></div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-bus-seat-clear>Boşalt</button><button class="ka-btn ka-btn--secondary" type="button" data-bus-seat-reserve>${seat.properties?.reserved&&!seat.studentId?'Rezervasyonu Kaldır':'Rezerve Et'}</button><button class="ka-btn ka-btn--secondary" type="button" data-bus-picker-close>Kapat</button></div></section>`;
  host.appendChild(picker);
  const closePicker=()=>picker.remove();
  picker.querySelectorAll('[data-bus-picker-close]').forEach(b=>b.onclick=closePicker);
  const bindStudents=()=>picker.querySelectorAll('[data-bus-student]').forEach(b=>b.onclick=()=>{if(assignBusStudent(index,b.dataset.busStudent)){closePicker();renderBusEditor(s)}});
  bindStudents();
  picker.querySelector('[data-bus-student-search]').oninput=e=>{picker.querySelector('[data-bus-student-list]').innerHTML=renderOptions(e.target.value);bindStudents()};
  picker.querySelector('[data-bus-seat-clear]').onclick=()=>{clearBusSeat(seat);closePicker();renderBusEditor(s)};
