const originalPrepare=typeof base.prepare==='function'?base.prepare.bind(base):null;
function requireReport(key){if(global.PermissionService){global.PermissionService.require('module.transport','preview');global.PermissionService.require(key,'preview')}}
async function prepare(){if(originalPrepare)await originalPrepare()}
function school(){const rows=arr('okulBilgileri');return rows.find(x=>x.id==='ayarlar')||rows[0]||{}}
function teachers(){return arr('ogretmenler')}
function personName(t){return t?`${t.ad||''} ${t.soyad||''}`.trim():''}
function admins(){const o=school(),ts=teachers(),mudur=ts.find(t=>t.id===o.mudurId)||ts.find(t=>(t.unvan||'').trim()==='Müdür'),yardimci=ts.find(t=>(t.unvan||'').trim()==='Müdür Yardımcısı');return{mudur:personName(mudur),yardimci:personName(yardimci),mudurId:mudur?.id||o.mudurId||'',yardimciId:yardimci?.id||''}}
function schoolTitle(){const o=school(),parts=[];if(o.il)parts.push(`${String(o.il).toLocaleUpperCase('tr')} İLİ`);if(o.ilce)parts.push(`${String(o.ilce).toLocaleUpperCase('tr')} İLÇESİ`);parts.push(String(o.okulAdi||'KORUK İLK-ORTAOKULU').toLocaleUpperCase('tr'));return parts.join(' ')}
function service(id){return arr('servisler').find(s=>s.id===id)||null}
function className(id,fallback=''){return arr('siniflar').find(s=>s.id===id)?.ad||fallback||id||''}
function studentSort(a,b){const c=String(a.sinif||'').localeCompare(String(b.sinif||''),'tr',{numeric:true});return c||String(a.ad||'').localeCompare(String(b.ad||''),'tr')}
function directStudents(servisId,s){const presidents=new Set(Array.isArray(s?.baskanlar)?s.baskanlar:[]);return arr('veliler').filter(v=>v.servisId===servisId).map(v=>({id:v.id,ad:v.ogrenciAdi||'',sinif:className(v.sinifId,v.sinifAdi),baskan:presidents.has(v.id)})).sort(studentSort)}
async function reportStudents(servisId,s){
 let list=directStudents(servisId,s),presidents=new Set(Array.isArray(s?.baskanlar)?s.baskanlar:[]);
 if(!list.length&&global.ServisOturmaRepository?.planServisIdIleGetir){
  try{
   const snap=await global.ServisOturmaRepository.planServisIdIleGetir(servisId),found=[];
   for(const doc of snap?.docs||[]){
    const p=doc.data?.()||{},seats=Array.isArray(p.koltuklar)?p.koltuklar:Object.values(p.koltuklar||{});
    for(const k of seats){if(k?.ogrenciAdi)found.push({id:k.ogrenciId||'',ad:k.ogrenciAdi,sinif:className(k.sinifId,k.sinifAdi),baskan:k.ogrenciId?presidents.has(k.ogrenciId):false})}
    if(!seats.length&&Array.isArray(p.elements))for(const el of p.elements){const n=el?.properties?.studentName;if(n)found.push({id:el.studentId||'',ad:n,sinif:className(el?.properties?.sinifId,el?.properties?.sinifAdi),baskan:el.studentId?presidents.has(el.studentId):false})}
   }
   const seen=new Set();list=found.filter(x=>{const k=x.id||`${x.ad}|${x.sinif}`;if(seen.has(k))return false;seen.add(k);return true}).sort(studentSort);
  }catch(_){list=[]}
 }
 const realCount=list.length;let target=Math.max(SABIT_LISTE_BOYU,realCount);if(target%2)target++;while(list.length<target)list.push({id:'',ad:'',sinif:'',baskan:false});return{list,target,realCount};
}
function dutyTeacherOptions(){const a=admins();return teachers().filter(t=>t.id!==a.mudurId&&(t.unvan||'').trim()!=='Müdür Yardımcısı').map(t=>personName(t)).filter(Boolean).sort((x,y)=>x.localeCompare(y,'tr')).map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}

function inspectionCss(){return `<style>
.ka-report{padding:7mm!important;font-family:'Segoe UI',Arial,sans-serif!important}.ka-report-content{display:block}.trp-inspection{color:#111}.trp-inspection .trp-head{text-align:center;margin-bottom:4px}.trp-inspection .trp-school{font-size:12.5pt;font-weight:800;letter-spacing:.2px}.trp-inspection .trp-head-1{font-size:9pt;font-weight:700;margin-top:2px}.trp-inspection .trp-head-2{font-size:10.5pt;font-weight:800;margin-top:2px}.trp-inspection .trp-head-3{font-size:7.5pt;font-style:italic;color:#333;margin-top:2px}.ka-report .trp-info{margin:6px 0!important;font-size:8.5pt!important;table-layout:fixed}.ka-report .trp-info td{border:1px solid #333!important;padding:3.5px 7px!important;background:#fff!important;color:#111!important;font-size:8.5pt!important}.ka-report .trp-info .trp-label{font-weight:800!important;white-space:nowrap;width:21%}.ka-report .trp-info .trp-value{width:29%;font-weight:600!important}.ka-report .trp-items{font-size:8pt!important;table-layout:fixed}.ka-report .trp-items th{border:1.4px solid #333!important;background:#fff!important;color:#111!important;padding:4px!important;font-size:8pt!important}.ka-report .trp-items td{border:1px solid #555!important;background:#fff!important;color:#111!important;padding:3.5px 6px!important;font-size:8pt!important;vertical-align:middle!important}.ka-report .trp-items .trp-topic{width:57%;text-align:left!important;line-height:1.2}.ka-report .trp-items .trp-answer{width:7%;text-align:center}.ka-report .trp-items .trp-explain{width:29%}.trp-ref{display:block;font-size:6.5pt;color:#555;font-style:italic;margin-top:1px}.trp-note{font-size:6.5pt;color:#333;margin-top:6px;line-height:1.3}.trp-signatures{display:flex;justify-content:space-around;margin-top:14px;gap:12px}.trp-signature{text-align:center;min-width:150px;flex:1}.trp-signature-title{font-size:8.3pt;font-weight:700;margin-bottom:16px}.trp-signature-line{border-top:1px solid #333;padding-top:3px}.trp-signature-name{font-size:8.6pt;font-weight:700;min-height:12px}.trp-signature-role{font-size:7.6pt;color:#444;margin-top:1px}.trp-duty-select{font-family:inherit;font-size:8.6pt;font-weight:700;border:none;border-bottom:1px solid #999;background:transparent;text-align:center;width:100%;padding:0}[contenteditable="true"]{outline:1px dashed transparent}[contenteditable="true"]:focus{outline-color:#9aa}.trp-duty-value{font-size:8.6pt;font-weight:700}@media print{[contenteditable="true"]{outline:none!important}.trp-duty-select{appearance:none;border:none!important}}
</style>`}
function inspectionItems(){return DENETIM_MADDELERI.map(([m,r])=>`<tr><td class="trp-topic"><span contenteditable="true" spellcheck="false">${esc(m)}</span><span class="trp-ref" contenteditable="true" spellcheck="false">(${esc(r)})</span></td><td class="trp-answer"></td><td class="trp-answer"></td><td class="trp-explain" contenteditable="true" spellcheck="false"></td></tr>`).join('')}
function inspectionBody(s,count){const a=admins();return `<div class="trp-inspection"><div class="trp-head"><div class="trp-school">${esc(schoolTitle())}</div><div class="trp-head-1">TAŞIMA YOLUYLA EĞİTİME ERİŞİM YÖNETMELİĞİ KAPSAMINDA HİZMET SUNAN</div><div class="trp-head-2">OKUL SERVİS ARACI DENETİM FORMU</div><div class="trp-head-3">(TAŞIMA MERKEZİ OKUL/KURUM MÜDÜRLÜĞÜNCE KULLANILACAK)</div></div><table class="trp-info"><tbody><tr><td class="trp-label">ARACIN PLAKASI</td><td class="trp-value" contenteditable="true" spellcheck="false">${esc(s.plaka||'')}</td><td class="trp-label">TELEFON / GSM</td><td class="trp-value" contenteditable="true" spellcheck="false">${esc(s.soforTelefon||'')}</td></tr><tr><td class="trp-label">ŞOFÖRÜN ADI SOYADI</td><td class="trp-value" contenteditable="true" spellcheck="false">${esc(s.soforAdi||'')}</td><td class="trp-label">ÖĞRENCİ SAYISI</td><td class="trp-value">${esc(count)}</td></tr><tr><td class="trp-label">ARACIN GÜZERGÂHI</td><td class="trp-value" contenteditable="true" spellcheck="false">${esc(s.guzergah||'')}</td><td class="trp-label">DENETLEME TARİHİ</td><td class="trp-value" contenteditable="true" spellcheck="false">…… / …… / 20……</td></tr><tr><td class="trp-label">ARACIN MODEL YILI</td><td class="trp-value" contenteditable="true" spellcheck="false">${esc(s.modelYili||'')}</td><td class="trp-label">SÜRÜCÜ BELGESİ YIL / SINIFI</td><td class="trp-value" contenteditable="true" spellcheck="false">${esc(s.ehliyetYili||'')}${s.ehliyetSinifi?` / ${esc(s.ehliyetSinifi)}`:''}</td></tr></tbody></table><table class="trp-items"><thead><tr><th class="trp-topic">DENETLEME KONULARI</th><th class="trp-answer">EVET</th><th class="trp-answer">HAYIR</th><th class="trp-explain">AÇIKLAMALAR</th></tr></thead><tbody>${inspectionItems()}</tbody></table><div class="trp-note">Not: 1) Okul servis araçları her haftanın ilk iş günü denetlenip bu form tutanak haline getirilerek ay sonu puantajları ile birlikte milli eğitim müdürlüğüne bildirilecek ve okul/kurum müdürlüğü dosyasında imzalı ve onaylı bir şekilde saklanacaktır. (bkz. Teknik Şartname)<br>2) Çizelgede yer alan denetim maddeleri ile ilgili “Evet / Hayır” bölümü işaretlendikten sonra gerek duyulması halinde “AÇIKLAMALAR” bölümü kullanılacaktır.</div><div class="trp-signatures"><div class="trp-signature"><div class="trp-signature-title">Denetleyen</div><div class="trp-signature-line"><div class="trp-signature-name"><select class="trp-duty-select" data-trp-duty-teacher><option value=""></option>${dutyTeacherOptions()}</select></div><div class="trp-signature-role">Nöbetçi Öğretmen</div></div></div><div class="trp-signature"><div class="trp-signature-title">Denetleyen</div><div class="trp-signature-line"><div class="trp-signature-name">${esc(a.yardimci)}</div><div class="trp-signature-role">Müdür Yardımcısı</div></div></div><div class="trp-signature"><div class="trp-signature-title">Denetleyen</div><div class="trp-signature-line"><div class="trp-signature-name">${esc(a.mudur)}</div><div class="trp-signature-role">Okul Müdürü</div></div></div></div></div>`}
function editablePreview(html,s){const ov=global.ReportEngine.previewHtml(html,{title:'Okul Servis Aracı Denetim Formu',fileName:`${s.plaka||'Servis'}_Denetim`,yon:'dikey'}),old=ov?.querySelector?.('[data-report-print]');if(!old)return ov;const btn=old.cloneNode(true);old.replaceWith(btn);btn.onclick=async()=>{const frame=ov.querySelector('#kaReportFrame'),doc=frame?.contentDocument;if(!doc)return global.toast?.('Rapor önizlemesi henüz hazır değil.');const duty=doc.querySelector('[data-trp-duty-teacher]')?.value||'',root=doc.documentElement.cloneNode(true),select=root.querySelector('[data-trp-duty-teacher]');if(select){const span=doc.createElement('span');span.className='trp-duty-value';span.textContent=duty;select.replaceWith(span)}root.querySelectorAll('[contenteditable]').forEach(x=>x.removeAttribute('contenteditable'));const printable='<!doctype html>'+root.outerHTML,oldText=btn.textContent;btn.disabled=true;btn.textContent='Hazırlanıyor…';try{await global.ReportEngine.printHtml(printable,`${s.plaka||'Servis'}_Denetim`,'dikey')}catch(e){global.toast?.('Yazdırma açılamadı: '+(e?.message||e))}finally{btn.disabled=false;btn.textContent=oldText}};return ov}
async function denetim(servisId){requireReport('transport.report.inspection');await prepare();const s=service(servisId);if(!s)throw new Error('servis-bulunamadi');const direct=directStudents(servisId,s),count=direct.length||s.ogrenciSayisi||'';const html=global.ReportEngine.documentHtml('Okul Servis Aracı Denetim Formu',inspectionBody(s,count),{yon:'dikey',logoGoster:false,tarihGoster:false,baslikGoster:false,kenarBosluk:7,fontSize:8,compact:true,extraHead:inspectionCss()});return editablePreview(html,s)}

